import json
import itertools

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4, 5, 6]
    names = ["Bob", "Peter", "Alice", "Eric", "Carol", "Arnold"]
    vacations = ["mountain", "camping", "cruise", "city", "cultural", "beach"]

    # Constraints as functions
    def valid_name_assignment(assignment):
        # assignment is a tuple/list of length 6 mapping house index 0..5 to a name

        # 2. Eric is somewhere to the right of Alice.
        if assignment.index("Eric") <= assignment.index("Alice"):
            return False

        # 3. Eric is in the second house.
        if assignment[1] != "Eric":
            return False

        # 7. The person who goes on cultural tours is Peter.
        # 4. The person who goes on cultural tours is in the third house.
        # From 4 and 7 together: Peter is in the third house.
        if assignment[2] != "Peter":
            return False

        # 5. Bob is directly left of Arnold.
        if assignment.index("Arnold") - assignment.index("Bob") != 1:
            return False

        return True

    def valid_vacation_assignment(assignment):
        # assignment is a tuple/list of length 6 mapping house index 0..5 to a vacation

        # 4. The person who goes on cultural tours is in the third house.
        if assignment[2] != "cultural":
            return False

        # 9. The person who prefers city breaks is in the fourth house.
        if assignment[3] != "city":
            return False

        # 6. The person who enjoys camping trips is not in the first house.
        if assignment[0] == "camping":
            return False

        # 1. The person who goes on cultural tours is somewhere to the left of the person who loves beach vacations.
        if assignment.index("cultural") >= assignment.index("beach"):
            return False

        return True

    # Generate all name assignments satisfying name-only constraints
    name_assignments = []
    for name_perm in itertools.permutations(names):
        if valid_name_assignment(name_perm):
            name_assignments.append(name_perm)

    # Generate all vacation assignments satisfying vacation-only constraints
    vacation_assignments = []
    for vac_perm in itertools.permutations(vacations):
        if valid_vacation_assignment(vac_perm):
            vacation_assignments.append(vac_perm)

    # Cross-validate combined constraints
    solutions = []
    for names_at in name_assignments:
        for vacs_at in vacation_assignments:
            # 7. The person who goes on cultural tours is Peter. (cross-check)
            if names_at[vacs_at.index("cultural")] != "Peter":
                continue

            # 8. The person who likes going on cruises is Bob.
            if names_at[vacs_at.index("cruise")] != "Bob":
                continue

            # 1. cultural left of beach is already enforced in vacations, but keep consistent

            # 2 and 3 already enforced in names

            # 6, 9 already enforced in vacations

            # 5 already enforced in names

            solutions.append((names_at, vacs_at))

    if not solutions:
        raise ValueError("No solution found with the given constraints.")

    # Assuming unique solution
    names_at, vacs_at = solutions[0]

    # Build output
    header = ["House", "Name", "Vacation"]
    rows = []
    for i in range(6):
        rows.append([str(houses[i]), names_at[i], vacs_at[i]])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
